// Snap to unique grid cells after a drag, and normalize earlier free layouts.
const cellMetrics=()=>({x:innerWidth<701?8:22,y:innerWidth<701?34:47,w:innerWidth<701?66:95,h:innerWidth<701?72:82});
function gridCells(){const m=cellMetrics(),b=bounds(),icon=desktopIcons[0];let cells=[];for(let col=0;m.x+col*m.w+icon.offsetWidth<=b.width;col++)for(let row=0;m.y+row*m.h+icon.offsetHeight<=b.height;row++)cells.push({x:m.x+col*m.w,y:m.y+row*m.h});return cells}
function snapIcons(moved=null){const cells=gridCells(),used=new Set();const order=moved?[...desktopIcons.filter(x=>x!==moved),moved]:desktopIcons;for(const icon of order){let x=icon.offsetLeft,y=icon.offsetTop,best=-1,distance=Infinity;cells.forEach((cell,i)=>{if(used.has(i))return;let d=(cell.x-x)**2+(cell.y-y)**2;if(d<distance){distance=d;best=i}});if(best>=0){used.add(best);const cell=cells[best];icon.classList.add('icon-snapping');placeIcon(icon,cell.x,cell.y);setTimeout(()=>icon.classList.remove('icon-snapping'),220)}}persistLayout()}
const freeArrange=arrangeIcons;arrangeIcons=function(reset=false){freeArrange(reset);snapIcons()};
desktopIcons.forEach(icon=>{icon.addEventListener('pointerup',()=>{snapIcons(icon)});icon.addEventListener('pointercancel',()=>snapIcons(icon));icon.addEventListener('keydown',e=>{if(e.altKey&&e.key.startsWith('Arrow'))queueMicrotask(()=>snapIcons(icon))})});snapIcons();
const gridSetupPrevious=setup;setup=function(id,w){const result=gridSetupPrevious(id,w);if(id==='settings'){let p=w.querySelector('.layout-settings p');if(p)p.textContent='Mueve tus iconos. Al soltarlos se alinean a la cuadrícula y buscan un espacio libre, sin encimarse.'}return result};
